Bug 2061218 - Save calendar event edits in new calendar edit dialog. r=#thunderbird-front-end-reviewers

Save updates or moves events through Calendar transactions and retains failed drafts for retry. Failed-move cleanup checks destination content and revision before deletion, preserving changes made by another editor.

Differential Revision: https://phabricator.services.mozilla.com/D332891


diff --git a/calendar/base/src/CalTransactionManager.sys.mjs b/calendar/base/src/CalTransactionManager.sys.mjs
index d06626d72ca..c6b3ba3c9f4 100644
--- a/calendar/base/src/CalTransactionManager.sys.mjs
+++ b/calendar/base/src/CalTransactionManager.sys.mjs
@@ -7,19 +7,77 @@ import { cal } from "resource:///modules/calendar/calUtils.sys.mjs";
 let transactionManager = null;

 /**
- * CalTransactionManager is used to track user initiated operations on calendar
- * items. These transactions can be undone or repeated when appropriate.
+ * A calendar provider implements item reads and writes. Moving an item between
+ * providers requires two writes: add a destination copy, then delete the source.
+ * If source deletion fails, cleanup tries to remove the destination copy.
+ * These records let a later edit retry cleanup if that removal also fails.
+ * They are separate from Undo, where failed transactions must not remain.
+ */
+
+/**
+ * Destination copies left by failed moves, grouped by source calendar and item
+ * IDs. These copies remain outside the Undo stack. Recovery records stay in
+ * memory until cleanup forgets each copy or this module is unloaded.
+ *
+ * @type {Map<string, Set<calIItemBase>>}
+ */
+const pendingMoveCopies = new Map();
+
+/**
+ * Removes unchanged destination copies left by failed moves for one source item.
+ * Forgets missing copies and copies changed by another edit. Keeps the recovery
+ * record if reading or deleting a copy fails, so the next edit can retry.
  *
- * This implementation is used instead of nsITransactionManager because better
- * support for async transactions and access to batch transactions is needed
- * which nsITransactionManager does not provide.
+ * @param {string} key - The JSON-encoded source calendar and item IDs.
+ * @returns {Promise<void>} Resolves after all recorded copies are checked.
+ * @throws If reading or deleting a destination copy fails.
+ */
+async function removePendingMoveCopies(key) {
+  const copies = pendingMoveCopies.get(key);
+  if (!copies) {
+    return;
+  }
+
+  for (const copy of copies) {
+    const current = await copy.calendar.getItem(copy.id);
+
+    // A revision identifies a saved version of the item. Empty ignore lists
+    // include revision properties in this comparison. Even when visible values
+    // match, a newer revision belongs to the later edit and must be preserved.
+    if (current && cal.item.compareContent(current, copy, [], {})) {
+      const provider = copy.calendar.wrappedJSObject;
+      if (provider?.deleteItemIfUnchanged) {
+        // Storage checks the revision again during deletion. Another edit can
+        // finish after getItem returns the snapshot checked here.
+        await provider.deleteItemIfUnchanged(current);
+      } else {
+        // Other providers use their normal deletion contract.
+        await copy.calendar.deleteItem(current);
+      }
+    }
+
+    // Forget missing or changed copies too. A failed read or deletion throws
+    // before this step, so the remaining records stay available for retry.
+    copies.delete(copy);
+  }
+
+  pendingMoveCopies.delete(key);
+}
+
+/**
+ * Records calendar changes as transactions that the user can undo or redo.
+ * Each transaction performs one change, such as an event edit. Undo calls the
+ * transaction's reverse operation. A batch groups changes into one Undo step.
+ *
+ * Calendar writes can finish later through promises. This manager supports
+ * those asynchronous writes and access to batches, unlike nsITransactionManager.
  */
 export class CalTransactionManager {
   /**
-   * Contains transactions executed by the transaction manager than can be
-   * undone.
+   * Contains transactions available for Undo, including work still pending.
+   * A failed commit removes its own transaction before reporting the error.
    *
-   * @type {CalTransaction}
+   * @type {CalTransaction[]}
    */
   undoStack = [];

@@ -27,7 +85,7 @@ export class CalTransactionManager {
    * Contains transactions that have been undone by the transaction manager and
    * can be redone again later if desired.
    *
-   * @type {CalTransaction}
+   * @type {CalTransaction[]}
    */
   redoStack = [];

@@ -53,15 +111,30 @@ export class CalTransactionManager {
    */

   /**
-   * Adds a CalTransaction to the internal stack. The transaction will be
-   * executed and its resulting Promise returned.
+   * Adds and executes a transaction. Removes the transaction if execution fails.
+   * Keeps other transactions available for Undo.
    *
    * @param {CalTransaction} trn - The CalTransaction to add to the stack and
    *                               execute.
+   * @returns {Promise<void>} Resolves after the transaction finishes. Removing
+   *   a failure from this stack does not reverse partial provider writes.
+   * @throws If the transaction fails.
    */
   async commit(trn) {
     this.undoStack.push(trn);
-    return trn.doTransaction();
+
+    try {
+      return await trn.doTransaction();
+    } catch (error) {
+      // A later transaction can finish while this transaction is pending.
+      // Remove this transaction by identity instead of removing the last entry.
+      const index = this.undoStack.indexOf(trn);
+      if (index != -1) {
+        this.undoStack.splice(index, 1);
+      }
+
+      throw error;
+    }
   }

   /**
