   mDeleteTodo = null;

+  /** @type {mozIStorageAsyncStatement[]} Event deletions that check the saved version. */
+  mDeleteEventIfUnchanged = [];
+
+  /** @type {mozIStorageAsyncStatement[]} Task deletions that check the saved version. */
+  mDeleteTodoIfUnchanged = [];
+
+  /** @type {mozIStorageAsyncStatement} The preceding master deletion's count. */
+  mSelectDeleteItemResult = null;
+
+  /** @type {mozIStorageAsyncStatement} Property deletion after a master deletion. */
+  mDeletePropertiesIfItemDeleted = null;
+
   /**
    * @type {mozIStorageAsyncStatement}
    */
@@ -687,6 +699,66 @@ export class CalStorageStatements {
       "DELETE FROM cal_alarms WHERE item_id = :item_id AND cal_id = :cal_id"
     );

+    for (const [table, stamp, statements] of [
+      ["cal_events", "event_stamp", this.mDeleteEventIfUnchanged],
+      ["cal_todos", "todo_stamp", this.mDeleteTodoIfUnchanged],
+    ]) {
+      // The master row describes the whole item; occurrence rows have a
+      // recurrence ID. Compare the master's timestamps and generation with the
+      // version captured for cleanup. SQL IS treats two NULL timestamps as
+      // equal. A missing X-MOZ-GENERATION means zero, as the item getter does.
+      const revisionMatches = `EXISTS (
+        SELECT 1 FROM ${table}
+         WHERE cal_id = :cal_id AND id = :id AND recurrence_id IS NULL
+           AND last_modified IS :last_modified AND ${stamp} IS :stamp
+           AND time_created IS :time_created
+      ) AND COALESCE((
+        SELECT CAST(value AS INTEGER) FROM cal_properties
+         WHERE cal_id = :cal_id AND item_id = :id AND recurrence_id IS NULL
+           AND key = 'X-MOZ-GENERATION'
+      ), 0) = :generation`;
+
+      // Related rows store attendees, rules, and other item data. Each deletion
+      // still needs the master row and generation property for its check.
+      // Keep those two sources until all these related rows have been checked.
+      for (const extra of [
+        "cal_attendees",
+        "cal_parameters",
+        "cal_recurrence",
+        "cal_attachments",
+        "cal_relations",
+        "cal_metadata",
+        "cal_alarms",
+      ]) {
+        statements.push(
+          db.createAsyncStatement(
+            `DELETE FROM ${extra}
+              WHERE item_id = :id AND cal_id = :cal_id AND ${revisionMatches}`
+          )
+        );
+      }
+
+      // Removing the master last leaves its deletion count available to the
+      // result query. A revision mismatch leaves the entire item unchanged.
+      statements.push(
+        db.createAsyncStatement(
+          `DELETE FROM ${table}
+            WHERE id = :id AND cal_id = :cal_id AND ${revisionMatches}`
+        )
+      );
+    }
+
+    this.mSelectDeleteItemResult = db.createAsyncStatement("SELECT changes() AS deleted");
+
+    // SQLite's changes() returns the number of rows changed by the last write.
+    // SELECT reads that count without replacing it. The count here therefore
+    // still describes the master deletion. Delete properties only if the master
+    // was deleted; their generation was needed by all earlier revision checks.
+    this.mDeletePropertiesIfItemDeleted = db.createAsyncStatement(
+      `DELETE FROM cal_properties
+        WHERE item_id = :item_id AND cal_id = :cal_id AND changes() > 0`
+    );
+
     // These are only used when deleting an entire calendar
     const extrasTables = [
       "cal_attendees",
@@ -743,5 +815,12 @@ export class CalStorageStatements {
     for (const stmt of this.mDeleteTodoExtras) {
       stmt.finalize();
     }
+
+    // Finalizing releases a prepared statement's database resources. The first
+    // loop visits only statements stored directly on this object. Release the
+    // statements inside these arrays separately.
+    for (const stmt of [...this.mDeleteEventIfUnchanged, ...this.mDeleteTodoIfUnchanged]) {
+      stmt.finalize();
+    }
   }
 }
